SELECT count(DISTINCT f.s7) AS a0, sum(CASE WHEN (f.s7 LIKE 'p%' OR f.s4 LIKE 'p%') THEN f.m15 ELSE 0 END) AS a1, sum(CASE WHEN (f.s0 LIKE 'p%' AND f.k4 IS NOT NULL) THEN f.m8 ELSE 0 END) AS a2, f.k10 AS c3, f.k12 AS c4, ((f.m0 - 78899) * (f.m15 - f.m9)) AS e5, avg(f.m10) AS a6, CASE WHEN count(*) > 17 THEN 'h' ELSE 'l' END AS s7, row_number() OVER (PARTITION BY f.k10 ORDER BY f.k6 DESC) AS w8, f.k1 AS c9, row_number() OVER (PARTITION BY f.k9 ORDER BY f.k11 DESC) AS w10, f.k9 AS c11 FROM fact_f0 f LEFT JOIN dim_d0 d0 ON f.k10 = d0.k10 INNER JOIN dim_d1 d1 ON f.k1 = d1.k1 JOIN (SELECT k0, sum(m0) AS sub_m0, count(*) AS sub_c0 FROM fact_f1 WHERE ts0 >= DATE '2024-01-01' GROUP BY k0) sub0 ON sub0.k0 = f.k0 WHERE f.ts0 BETWEEN DATE '2024-01-01' AND DATE '2024-12-31' AND f.k2 IN (9874, 7515, 659, 9979, 1082, 5868, 2765, 6850, 4216, 4405, 34, 1517, 1316, 5291, 3559, 4228, 1684, 4625, 5503, 6370, 1640, 4840, 2795, 8479, 8892, 3085, 2793, 5081, 2276, 2451, 1494, 1257, 4572, 2259, 6675, 5449, 7287, 9101, 3665, 3260) AND f.k3 NOT IN (8749, 472, 9323, 8926, 1441, 8850, 3603, 5951, 6083, 5970) AND f.m0 > 0 GROUP BY f.k3, f.k12, f.k6 HAVING count(*) > 1 AND sum(f.m0) > 0 ORDER BY a0 DESC NULLS LAST, c1 ASC, e2 DESC LIMIT 1000
